#!/usr/bin/env bash
set -euo pipefail

VERSION="cg-multilane-v1.3"
STATE_DIR="${CG_LANE_STATE_DIR:-$HOME/.chatgpt-lanes}"
OUTPUT_DIR="${CG_OUTPUT_DIR:-$HOME/.chatgpt-output}"
CURRENT_FILE="$STATE_DIR/current_lane"
LANES_DIR="$STATE_DIR/lanes"
LOCKS_DIR="$STATE_DIR/locks"
RUNS_DIR="$STATE_DIR/runs"

log() { printf '%s\n' "$*"; }
die() { printf 'FAIL: %s\n' "$*" >&2; (exit 1); }
sanitize_id() { local raw="${1:-}" label="${2:-id}"; [ -n "$raw" ] || die "${label}_missing"; raw="$(printf '%s' "$raw" | tr '[:upper:]' '[:lower:]')"; case "$raw" in *[!a-z0-9._-]*) die "${label}_invalid_chars allowed=a-z0-9._- value=$raw" ;; esac; [ "${#raw}" -le 80 ] || die "${label}_too_long"; printf '%s\n' "$raw"; }
meta_path() { printf '%s/%s/meta.env\n' "$LANES_DIR" "$1"; }
write_meta() { local lane="$1" scope="$2" host="$3" route="$4" secret="$5" reason="${6:-manual}"; mkdir -p "$LANES_DIR/$lane"; { printf 'CG_LANE_ID=%s\nCG_LANE_SCOPE=%s\nCG_LANE_HOST=%s\nCG_LANE_ROUTE_CLASS=%s\nCG_LANE_SECRET_CLASS=%s\nCG_LANE_REASON=%s\nCG_LANE_UPDATED_AT=%s\nCG_LANE_VERSION=%s\n' "$lane" "$scope" "$host" "$route" "$secret" "$reason" "$(date -Is)" "$VERSION"; } >"$(meta_path "$lane")"; }
require_init() { mkdir -p "$LANES_DIR" "$LOCKS_DIR" "$RUNS_DIR" "$OUTPUT_DIR"; if [ ! -s "$CURRENT_FILE" ]; then printf 'default\n' >"$CURRENT_FILE"; write_meta default pixel pixel-local none none bootstrap; fi; }
current_lane() { require_init; sanitize_id "$(cat "$CURRENT_FILE")" lane; }
read_meta_value() { local lane="$1" key="$2" file; file="$(meta_path "$lane")"; [ -f "$file" ] || return 1; awk -F= -v k="$key" '$1==k {print substr($0,length($1)+2)}' "$file" | tail -n1; }
route_guard() { case "$1" in none|read-only|route|dns-ha|magicdns|subnet-route) return 0 ;; route-sensitive|default-route) die "route_class_legacy_unsupported route_class=$1" ;; *) die "route_class_unknown route_class=$1" ;; esac; }
secret_guard() { case "$1" in none|public|redacted|possible|sensitive) return 0 ;; *) die "secret_class_unknown secret_class=$1" ;; esac; }
proc_start_ticks() { awk '{print $22}' "/proc/$1/stat" 2>/dev/null || true; }
lock_owner_is_live() { local path="$1" pid stored current; pid="$(cat "$path/pid" 2>/dev/null || true)"; case "$pid" in ''|*[!0-9]*) return 1 ;; esac; kill -0 "$pid" 2>/dev/null || return 1; stored="$(cat "$path/pid_start_ticks" 2>/dev/null || true)"; [ -z "$stored" ] && return 0; current="$(proc_start_ticks "$pid")"; [ -n "$current" ] && [ "$current" = "$stored" ]; }

cmd_init() { require_init; log "version=$VERSION"; log "state_dir=$STATE_DIR"; log "output_dir=$OUTPUT_DIR"; log "RESULT: CG_MULTILANE_INIT_OK"; }
cmd_use() { require_init; local lane scope host route secret; lane="$(sanitize_id "${1:-}" lane)"; scope="$(sanitize_id "${2:-pixel}" scope)"; host="$(sanitize_id "${3:-pixel-local}" host)"; route="${4:-none}"; secret="${5:-none}"; route_guard "$route"; secret_guard "$secret"; write_meta "$lane" "$scope" "$host" "$route" "$secret" cguse; printf '%s\n' "$lane" >"$CURRENT_FILE"; printf 'lane=%s\nscope=%s\nhost=%s\nroute_class=%s\nsecret_class=%s\nRESULT: CG_MULTILANE_USE_OK\n' "$lane" "$scope" "$host" "$route" "$secret"; }
cmd_current() { local lane; lane="$(current_lane)"; log "lane=$lane"; [ ! -f "$(meta_path "$lane")" ] || cat "$(meta_path "$lane")"; log "RESULT: CG_MULTILANE_CURRENT_OK"; }
cmd_list() { require_init; local cur; cur="$(current_lane)"; log '== lanes =='; find "$LANES_DIR" -mindepth 1 -maxdepth 1 -type d -printf '%f\n' 2>/dev/null | sort | while IFS= read -r lane; do [ -n "$lane" ] || continue; mark=' '; [ "$lane" = "$cur" ] && mark='*'; printf '%s %s scope=%s host=%s route=%s secret=%s\n' "$mark" "$lane" "$(read_meta_value "$lane" CG_LANE_SCOPE 2>/dev/null || printf unknown)" "$(read_meta_value "$lane" CG_LANE_HOST 2>/dev/null || printf unknown)" "$(read_meta_value "$lane" CG_LANE_ROUTE_CLASS 2>/dev/null || printf unknown)" "$(read_meta_value "$lane" CG_LANE_SECRET_CLASS 2>/dev/null || printf unknown)"; done; log 'RESULT: CG_MULTILANE_LIST_OK'; }
cmd_status() { require_init; local cur; cur="$(current_lane)"; printf 'version=%s\nstate_dir=%s\noutput_dir=%s\ncurrent_lane=%s\n== locks ==\n' "$VERSION" "$STATE_DIR" "$OUTPUT_DIR" "$cur"; find "$LOCKS_DIR" -mindepth 1 -maxdepth 1 -type d -printf '%f\n' 2>/dev/null | sort || true; log '== lane status =='; find "$LANES_DIR" -mindepth 1 -maxdepth 1 -type d -printf '%f\n' 2>/dev/null | sort | while IFS= read -r lane; do [ -n "$lane" ] || continue; runid="$(cat "$LANES_DIR/$lane/latest.run_id" 2>/dev/null || true)"; logpath="$(cat "$LANES_DIR/$lane/latest.path" 2>/dev/null || true)"; bytes=missing; lines=missing; result=missing; if [ -f "$logpath" ]; then bytes="$(wc -c <"$logpath" | tr -d ' ')"; lines="$(wc -l <"$logpath" | tr -d ' ')"; result="$(grep -E 'RESULT:|FAIL:|ERROR:|STOP:' "$logpath" | tail -n1 || true)"; fi; printf '%s run=%s bytes=%s lines=%s last="%s"\n' "$lane" "${runid:-none}" "$bytes" "$lines" "$result"; done; log 'RESULT: CG_MULTILANE_STATUS_OK'; }
cmd_tail() { require_init; local lane_or_run="${1:-$(current_lane)}" lines="${2:-120}" logpath="" lane; case "$lines" in *[!0-9]*|'') die lines_must_be_integer ;; esac; if [ -f "$RUNS_DIR/$lane_or_run/log.path" ]; then logpath="$(cat "$RUNS_DIR/$lane_or_run/log.path")"; else lane="$(sanitize_id "$lane_or_run" lane)"; logpath="$(cat "$LANES_DIR/$lane/latest.path" 2>/dev/null || true)"; fi; [ -n "$logpath" ] || die "log_not_found target=$lane_or_run"; [ -f "$logpath" ] || die "log_path_missing path=$logpath"; printf '== cgtail-lane target=%s lines=%s log=%s ==\n' "$lane_or_run" "$lines" "$logpath"; tail -n "$lines" "$logpath"; printf 'RESULT: CG_MULTILANE_TAIL_OK chat_lane=%s\n' "$lane_or_run"; }
cmd_run_file() { require_init; local script="${1:-}" mode="${2:-verify}" scope="${3:-}" driver; [ -n "$script" ] || die script_arg_missing; mode="$(printf '%s' "$mode" | tr '[:upper:]' '[:lower:]')"; case "$mode" in verify|run) ;; *) die "run_mode_invalid value=$mode" ;; esac; driver="$(command -v cg-run-file-driver-v1 2>/dev/null || true)"; [ -n "$driver" ] && [ -s "$driver" ] || die cg_run_file_driver_missing; bash "$driver" run "$script" "$mode" "$scope"; }
cmd_adopt() { require_init; local logpath="${1:-}" lane="${2:-$(current_lane)}" run_id; [ -n "$logpath" ] || die logpath_missing; logpath="$(readlink -f "$logpath")"; [ -f "$logpath" ] || die "logpath_not_file path=$logpath"; lane="$(sanitize_id "$lane" lane)"; run_id="adopted_$(date +%Y%m%d_%H%M%S)_$lane"; mkdir -p "$RUNS_DIR/$run_id" "$LANES_DIR/$lane"; printf '%s\n' "$logpath" >"$RUNS_DIR/$run_id/log.path"; printf 'adopted\n' >"$RUNS_DIR/$run_id/rc"; ln -sfn "$logpath" "$LANES_DIR/$lane/latest.log"; printf '%s\n' "$logpath" >"$LANES_DIR/$lane/latest.path"; printf '%s\n' "$run_id" >"$LANES_DIR/$lane/latest.run_id"; printf 'RESULT: CG_MULTILANE_ADOPT_OK chat_lane=%s run_id=%s log=%s\n' "$lane" "$run_id" "$logpath"; }
cmd_unlock_stale() { require_init; local lock="${1:-}" path; [ -n "$lock" ] || die lock_missing; lock="$(sanitize_id "$lock" lock)"; path="$LOCKS_DIR/$lock"; [ -d "$path" ] || die "lock_not_found lock=$lock"; if lock_owner_is_live "$path"; then die "lock_owner_live lock=$lock pid=$(cat "$path/pid" 2>/dev/null || true)"; fi; rm -rf "$path"; printf 'RESULT: CG_MULTILANE_UNLOCK_STALE_OK lock=%s\n' "$lock"; }
usage() { printf '%s\n' 'Usage:' '  cg-lane.sh init' '  cg-lane.sh use <lane> [scope] [host] [route_class] [secret_class]' '  cg-lane.sh current' '  cg-lane.sh list' '  cg-lane.sh status' '  cg-lane.sh tail [lane_or_run_id] [lines]' '  cg-lane.sh run-file <script> [mode] [scope]' '  cg-lane.sh adopt <log_path> [lane]' '  cg-lane.sh unlock-stale <lock>'; }
main() { local cmd="${1:-}"; shift || true; case "$cmd" in init) cmd_init "$@" ;; use) cmd_use "$@" ;; current) cmd_current "$@" ;; list) cmd_list "$@" ;; status) cmd_status "$@" ;; tail) cmd_tail "$@" ;; run-file) cmd_run_file "$@" ;; adopt) cmd_adopt "$@" ;; unlock-stale) cmd_unlock_stale "$@" ;; -h|--help|help|'') usage ;; *) die "unknown_command=$cmd" ;; esac; }
main "$@"
